custom_fields.canvas:
[[[
  const dateTime = states["sensor.date_time"]?.state || "";
  const timePart = dateTime.split(", ")[1] || "";
  const isDaytime = states["sun.sun"]?.state === "above_horizon";
  const [hourRaw, minuteRaw] = timePart.split(":");
  const hour = Number(hourRaw);
  const minute = minuteRaw || "00";
  const meridiem = hour >= 12 ? "PM" : "AM";
  const displayHour = hour % 12 || 12;
  const timeLabel = `${displayHour}:${minute}`;
  const weather = states["weather.forecast_housevoice_weather"];
  const weatherState = weather?.state || "";
  const weatherIcons = {"clear-night": "mdi:weather-night", sunny: "mdi:weather-sunny", partlycloudy: "mdi:weather-partly-cloudy", cloudy: "mdi:weather-cloudy", rainy: "mdi:weather-rainy", pouring: "mdi:weather-pouring", snowy: "mdi:weather-snowy", "snowy-rainy": "mdi:weather-snowy-rainy", lightning: "mdi:weather-lightning", "lightning-rainy": "mdi:weather-lightning-rainy", fog: "mdi:weather-fog", windy: "mdi:weather-windy", "windy-variant": "mdi:weather-windy-variant"};
  const weatherLabels = {"clear-night": "Clear Night", sunny: "Sunny", partlycloudy: "Partly Cloudy", cloudy: "Cloudy", rainy: "Rainy", pouring: "Pouring", snowy: "Snowy", "snowy-rainy": "Snowy Rain", lightning: "Lightning", "lightning-rainy": "Thunderstorms", fog: "Fog", windy: "Windy", "windy-variant": "Windy"};
  const weatherIcon = weatherIcons[weatherState] || "mdi:weather-cloudy";
  const weatherLabel = weatherLabels[weatherState] || "Unknown";
  const weatherTemperature = Number(weather?.attributes?.temperature);
  const weatherHumidity = Number(weather?.attributes?.humidity);
  const roomTemperature = Number(states["sensor.t6_pro_z_wave_programmable_thermostat_air_temperature"]?.state); const roomHumidity = Number(states["sensor.t6_pro_z_wave_programmable_thermostat_humidity"]?.state); const alarmState = states["alarm_control_panel.alarmo"]?.state || "unknown"; const alarmLabels = { disarmed: "Disarmed", armed_home: "Armed Home", armed_away: "Armed Away", armed_night: "Armed Night", triggered: "Triggered", pending: "Pending", arming: "Arming" }; const alarmColor = { disarmed: "#73e876", armed_home: "#ff8c00", armed_away: "#ff4444", armed_night: "#b966ff", triggered: "#ff0000", pending: "#ffaa00", arming: "#ffaa00" }[alarmState] || "#b966ff"; const alarmLabel = alarmLabels[alarmState] || "Unknown"; const openLocks = ["input_boolean.front_door_locked_mock", "input_boolean.back_door_locked_mock", "input_boolean.garage_entry_locked_mock"].filter(id => states[id]?.state !== "on").length; const locksLabel = Number.isFinite(openLocks) ? (openLocks > 0 ? openLocks + " Unlocked" : "All Locked") : "Unknown"; const garageClosed = states["input_boolean.garage_door_closed_mock"]?.state === "on"; const garageLabel = garageClosed ? "Closed" : "Open"; const bedroomLightOn = states["input_boolean.primary_bedroom_light"]?.state === "on"; localStorage.setItem("housevoice_home", "/parents-room/parents-room");

  return `
<div class="parents-canvas ${isDaytime ? "daytime" : "nighttime"}">
  <div class="parents-clock" aria-label="Current time and weather">
    <div class="clock-line">
      <span class="clock-time">${timeLabel}</span>
      <span class="clock-meridiem">${meridiem}</span>
    </div>
    <div class="clock-weather">
      <ha-icon icon="${weatherIcon}"></ha-icon>
      <span>${Number.isFinite(weatherTemperature) ? Math.round(weatherTemperature) : "--"}°</span>
    </div>
  </div>

  <div class="parents-brand">
    <img src="/local/housevoice/logo.svg?v=5" alt="HouseVoice">
    <div class="brand-copy">
      <div class="brand-name">HOUSEVOICE</div>
      <div class="brand-room">PARENTS' ROOM</div>
    </div>
  </div>

  <section class="glass-panel glance-panel">
    <h2>AT A GLANCE</h2>
    <div class="glance-row"><ha-icon icon="mdi:shield-star-outline"></ha-icon><span>Alarm</span><strong style="color:${alarmColor};">${alarmLabel}</strong></div>
    <div class="glance-row"><ha-icon icon="mdi:lock-outline"></ha-icon><span>Locks</span><strong style="color:${openLocks > 0 ? "#ff5a52" : "#73e876"};">${locksLabel}</strong></div>
    <div class="glance-row"><ha-icon icon="mdi:garage"></ha-icon><span>Garage</span><strong style="color:${garageClosed ? "#73e876" : "#ff5a52"};">${garageLabel}</strong></div>
    <div class="glance-row"><ha-icon icon="mdi:thermometer"></ha-icon><span>Temp</span><strong class="neutral">${Number.isFinite(roomTemperature) ? Math.round(roomTemperature) : "--"}°</strong></div>
    <div class="glance-row"><ha-icon icon="mdi:water-outline"></ha-icon><span>Humidity</span><strong class="neutral">${Number.isFinite(roomHumidity) ? Math.round(roomHumidity) : "--"}%</strong></div>
  </section>

  <section class="glass-panel quick-panel">
    <h2>QUICK ACTIONS</h2>
    <div class="quick-action light-action"><ha-icon icon="mdi:lightbulb-outline"></ha-icon><div><b>BEDROOM LIGHT</b><span>${bedroomLightOn ? "On" : "Off"}</span></div></div>
    <div class="quick-action music-action"><ha-icon icon="mdi:music-note-outline"></ha-icon><div><b>MUSIC</b><span>Not Playing</span></div></div>
    <div class="quick-action intercom-action"><ha-icon icon="mdi:cellphone-basic"></ha-icon><div><b>INTERCOM</b><span>Choose Room</span></div></div>
  </section>

  <nav class="parents-nav">
    <a class="parents-nav-item alarm-nav" href="/control-panels/alarm-control?housevoice_origin=parents"><ha-icon icon="mdi:shield-star-outline"></ha-icon><span>ALARM</span></a>
    <a class="parents-nav-item lights-nav" href="/control-panels/lights-control?housevoice_origin=parents"><ha-icon icon="mdi:lightbulb-outline"></ha-icon><span>LIGHTS</span></a>
    <a class="parents-nav-item locks-nav" href="/control-panels/locks-control?housevoice_origin=parents"><ha-icon icon="mdi:lock-outline"></ha-icon><span>LOCKS</span></a>
    <a class="parents-nav-item cameras-nav" href="/control-panels/cameras-control?housevoice_origin=parents"><ha-icon icon="mdi:cctv"></ha-icon><span>CAMERAS</span></a>
    <a class="parents-nav-item temp-nav" href="/control-panels/thermostat-control?housevoice_origin=parents"><ha-icon icon="mdi:thermometer"></ha-icon><span>TEMP</span></a>
  </nav>
</div>`;
]]]

cards.extra_styles:
:host {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.parents-canvas {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100dvh;
  overflow: hidden;
  color: #f4f7fa;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background:
    linear-gradient(180deg, rgba(2, 12, 31, .24) 0%, rgba(2, 10, 26, .04) 46%, rgba(1, 7, 19, .18) 100%),
    url('/local/housevoice/Lake-Louise_at-Dusk.png') center center / cover no-repeat;
}

.parents-canvas.daytime {
  background-image:
    linear-gradient(180deg, rgba(228, 241, 255, .18) 0%, rgba(255, 250, 232, .04) 48%, rgba(1, 5, 14, .10) 100%),
    url('/local/housevoice/assets/references/lake%20louise%20daytime.png');
}

.parents-clock {
  position: absolute;
  z-index: 2;
  top: 1.6vh;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  color: #f8fbff;
  text-shadow: 0 3px 18px rgba(0, 0, 0, .44);
  white-space: nowrap;
}

.clock-line {
  display: flex;
  align-items: flex-end;
  line-height: .86;
}

.clock-time {
  font-size: clamp(90px, 12.5vw, 126px);
  font-weight: 300;
  letter-spacing: -5px;
}

.clock-meridiem {
  margin: 0 0 7px 12px;
  font-size: clamp(34px, 4.2vw, 46px);
  font-weight: 300;
  letter-spacing: 1px;
}

.clock-weather {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 14px;
  font-size: clamp(27px, 3.5vw, 36px);
  font-weight: 300;
  line-height: 1;
}

.clock-weather ha-icon {
  --mdc-icon-size: clamp(31px, 4vw, 42px);
}

.parents-brand {
  position: absolute;
  z-index: 2;
  top: 5.3vh;
  right: 4.8vw;
  display: flex;
  align-items: center;
  gap: clamp(10px, 1.3vw, 17px);
  color: #f4f7fa;
  text-shadow: 0 2px 12px rgba(0, 0, 0, .34);
}

.parents-brand img {
  width: clamp(68px, 7.3vw, 88px);
  height: auto;
  object-fit: contain;
}

.brand-copy {
  text-align: center;
}

.brand-name {
  font-size: clamp(22px, 2.55vw, 30px);
  font-weight: 400;
  letter-spacing: clamp(6px, .75vw, 9px);
  white-space: nowrap;
}

.brand-room {
  margin-top: 7px;
  color: #53c8ff;
  font-size: clamp(11px, 1.3vw, 15px);
  font-weight: 500;
  letter-spacing: clamp(5px, .7vw, 8px);
  white-space: nowrap;
}

.glass-panel {
  position: absolute;
  z-index: 2;
  top: 26vh;
  box-sizing: border-box;
  width: 27.5vw;
  height: 45vh;
  border: 1px solid rgba(121, 178, 215, .34);
  border-radius: clamp(17px, 2vw, 23px);
  background: linear-gradient(145deg, rgba(5, 22, 39, .89), rgba(2, 14, 29, .83));
  box-shadow: 0 12px 30px rgba(0, 0, 0, .28), inset 0 1px 0 rgba(255, 255, 255, .055);
  backdrop-filter: blur(11px);
}

.glance-panel {
  left: 4.7vw;
  padding: 2.3vh 2.15vw 1.7vh;
}

.quick-panel {
  right: 4.7vw;
  padding: 2.3vh 1.8vw;
}

h2 {
  margin: 0 0 1.6vh;
  color: #59d2ff;
  font-size: clamp(18px, 2vw, 22px);
  font-weight: 500;
  letter-spacing: clamp(3px, .45vw, 6px);
  line-height: 1.1;
  white-space: nowrap;
}

.glance-row {
  display: grid;
  grid-template-columns: clamp(29px, 3.3vw, 38px) minmax(0, 1fr) auto;
  align-items: center;
  height: calc((100% - 34px) / 5);
  border-bottom: 1px solid rgba(137, 169, 199, .18);
  column-gap: clamp(8px, 1.1vw, 13px);
  white-space: nowrap;
}

.glance-row:last-child {
  border-bottom: 0;
}

.glance-row ha-icon {
  color: #f4f8fb;
  --mdc-icon-size: clamp(27px, 3.15vw, 35px);
}

.glance-row > span {
  color: rgba(247, 250, 253, .96);
  font-size: clamp(17px, 1.85vw, 21px);
  font-weight: 400;
  text-align: left;
  justify-self: start;
}

.glance-row strong {
  justify-self: end;
  font-size: clamp(17px, 1.85vw, 21px);
  font-weight: 600;
}

.glance-row strong.neutral {
  color: #f4f7fa;
}

.quick-action {
  position: relative;
  display: grid;
  grid-template-columns: clamp(46px, 5.2vw, 58px) 1fr;
  align-items: center;
  box-sizing: border-box;
  height: 10.6vh;
  min-height: 58px;
  margin-bottom: 1.5vh;
  padding: 0 clamp(13px, 1.5vw, 18px);
  border: 1px solid rgba(120, 165, 205, .39);
  border-radius: clamp(14px, 1.8vw, 19px);
  background: linear-gradient(135deg, rgba(18, 34, 54, .91), rgba(5, 18, 33, .87));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .055), 0 5px 15px rgba(0, 0, 0, .20);
}

.quick-action:last-child {
  margin-bottom: 0;
}

.quick-action ha-icon {
  --mdc-icon-size: clamp(36px, 4.2vw, 46px);
  justify-self: center;
}

.quick-action > div {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 5px;
  min-width: 0;
  padding-left: clamp(8px, .9vw, 11px);
}

.quick-action b {
  width: 100%;
  color: #f5f8fb;
  font-size: clamp(17px, 1.8vw, 20px);
  font-weight: 600;
  letter-spacing: .3px;
  text-align: left;
  white-space: nowrap;
}

.quick-action span {
  width: 100%;
  color: rgba(239, 242, 247, .82);
  font-size: clamp(15px, 1.6vw, 18px);
  text-align: left;
  white-space: nowrap;
}

.light-action {
  border-color: rgba(255, 207, 111, .46);
}

.light-action ha-icon {
  color: #ffd16e;
}

.music-action {
  border-color: rgba(173, 126, 237, .54);
}

.music-action ha-icon {
  color: #c795ff;
}

.intercom-action {
  border-color: rgba(83, 185, 255, .50);
}

.intercom-action ha-icon,
.intercom-action b {
  color: #67cbff;
}

.parents-nav {
  position: absolute;
  z-index: 2;
  left: 4vw;
  right: 4vw;
  bottom: 5vh;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  height: 16vh;
  min-height: 88px;
  box-sizing: border-box;
  border: 1px solid rgba(115, 160, 195, .36);
  border-radius: clamp(17px, 2vw, 23px);
  background: linear-gradient(180deg, rgba(6, 24, 43, .94), rgba(2, 14, 29, .95));
  box-shadow: 0 12px 31px rgba(0, 0, 0, .30), inset 0 1px 0 rgba(255, 255, 255, .06);
  backdrop-filter: blur(11px);
  overflow: hidden;
}

.parents-nav-item {
  color: inherit;
  text-decoration: none;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: clamp(7px, 1.2vh, 11px);
  border-right: 1px solid rgba(150, 185, 215, .18);
}

.parents-nav-item:last-child {
  border-right: 0;
}

.parents-nav-item ha-icon {
  --mdc-icon-size: clamp(38px, 4.35vw, 48px);
}

.parents-nav-item span {
  font-size: clamp(16px, 1.75vw, 20px);
  font-weight: 500;
  letter-spacing: clamp(1px, .18vw, 2px);
}

.alarm-nav ha-icon { color: #64c8ff; }
.lights-nav ha-icon { color: #ffd16e; }
.locks-nav ha-icon { color: #79e86c; }
.cameras-nav ha-icon { color: #f3f5f8; }
.temp-nav ha-icon { color: #68cbff; }

.parents-canvas.daytime .parents-clock,
.parents-canvas.daytime .parents-brand {
  color: #062b55;
  text-shadow: 0 2px 14px rgba(255, 255, 255, .28);
}

.parents-canvas.daytime .brand-room {
  color: #0a5a8f;
}
